using System.Reactive;

namespace Tests.System.Reactive.Shared;

/// <summary>
/// Describes <c>Seq.FromEventPattern(addHandler, removeHandler[, scheduler])</c> over an
/// <c>EventHandler&lt;TEventArgs&gt;</c> event.
/// </summary>
/// <typeparam name="TEventArgs">The type of the event data generated by the event.</typeparam>
/// <remarks>
/// Built by the <c>Seq.FromEventPattern</c> overloads in <c>Seq.FromEventPattern.cs</c>;
/// materialized by each
/// target through <see cref="ISeqVisitor.FromEventPattern{TEventArgs}(FromEventPatternSeq{TEventArgs})"/>.
/// </remarks>
public sealed class FromEventPatternSeq<TEventArgs>(Action<EventHandler<TEventArgs>> addHandler,
        Action<EventHandler<TEventArgs>> removeHandler, SchedulerRef? scheduler)
    : Seq<EventPattern<TEventArgs>>
{
    /// <summary>
    /// Action that attaches the given event handler to the underlying .NET event.
    /// </summary>
    public Action<EventHandler<TEventArgs>> AddHandler => addHandler;

    /// <summary>
    /// Action that detaches the given event handler from the underlying .NET event.
    /// </summary>
    public Action<EventHandler<TEventArgs>> RemoveHandler => removeHandler;

    /// <summary>
    /// Scheduler to run the event conversion on, or null for the target's default.
    /// </summary>
    public SchedulerRef? Scheduler => scheduler;

    /// <inheritdoc/>
    protected override Realized<Seq<EventPattern<TEventArgs>>> AcceptCore(ISeqVisitor visitor) =>
        visitor.FromEventPattern(this);

    /// <inheritdoc/>
    public override string ToString() =>
        scheduler is null
            ? "Seq.FromEventPattern(addHandler, removeHandler)"
            : $"Seq.FromEventPattern(addHandler, removeHandler, {scheduler})";
}
